.flex-container {
  display: flex; /* Makes this element a flex container */
  background-color: #f0f0f0;
  padding: 10px;
}

.flex-item {
  background-color: #add8e6;
  margin: 5px;
  padding: 15px;
  border: 1px solid #333;
}

.row-container {
  display: flex;
  flex-direction: row; /* Main axis is horizontal */
  /* Items will flow left-to-right */
}

.column-container {
  display: flex;
  flex-direction: column; /* Main axis is vertical */
  /* Items will flow top-to-bottom */
}

.container-row-wrap {
  display: flex;
  flex-direction: row; /* Items flow horizontally */
  flex-wrap: wrap;     /* Items wrap to next line if needed */
}

.container-column-nowrap {
  display: flex;
  flex-direction: column; /* Items flow vertically */
  flex-wrap: nowrap;      /* Items stay on one line */
}

.justify-center {
  display: flex;
  justify-content: center; /* Centers items along main axis */
}

.justify-space-between {
  display: flex;
  justify-content: space-between; /* Evenly spaces items */
}

.align-center {
  display: flex;
  align-items: center; /* Centers items vertically (cross-axis) */
  height: 100px; /* For visual effect */
}

.align-content-space {
  display: flex;
  flex-wrap: wrap;
  align-content: space-around; /* Distributes space between lines */
  height: 200px; /* For multiple lines */
}

.flex-container {
  display: flex;
}

.item-one { order: 2; } /* Will appear after item with order 1 or 0 */
.item-two { order: 0; } /* Will appear first (default is 0) */
.item-three { order: 1; } /* Will appear between item two and one */

.item-grow {
  flex-grow: 1;    /* Item will grow to fill available space */
  flex-basis: 0;   /* Initial size is 0 before growth */
}

.item-shrink {
  flex-shrink: 0;  /* Item will not shrink below its content size */
  flex-basis: 150px; /* Initial size is 150px */
}

.flex-container {
  display: flex;
  align-items: flex-start; /* Default for all items */
  height: 150px;
}

.item-special {
  flex: 1 1 100px; /* Grow 1, Shrink 1, Basis 100px */
  align-self: center; /* Override container's align-items */
}

.item-default {
  flex: 1; /* Shorthand for 1 1 0% */
}
